getCookieByName=function(o){var e=document.cookie.match(new RegExp("(^| )"+o+"=([^;]+)"));if(e)return e[2]};var cookie=null;window.onload=function(){cookie=getCookieByName("PHPSESSID")},$("form").submit(function(o){var e=getCookieByName("PHPSESSID");if(cookie!==e){o.preventDefault();var i=window.location;window.location.href=i.protocol+"//"+i.host+"/hotel-edit-profile-details/?ok=4083"}});